using System;
using System.Collections.Generic;
using System.ComponentModel;
using System.Drawing;
using System.IO;
using System.Linq;
using System.Reflection;
using System.Text;
using System.Windows.Forms;
namespace DoomSNESed {
    public static class InteractionTests {
        static void Check(bool value,string message){Bin.Require(value,"Interaction/converter test: "+message);}
        static object Call(object o,string name,params object[] args){return o.GetType().GetMethod(name,BindingFlags.Instance|BindingFlags.NonPublic).Invoke(o,args);}
        static object Field(object o,string name){return o.GetType().GetField(name,BindingFlags.Instance|BindingFlags.NonPublic).GetValue(o);}
        static byte[] Data(Action<BinaryWriter> action){using(var s=new MemoryStream())using(var w=new BinaryWriter(s)){action(w);return s.ToArray();}}
        static void Name(BinaryWriter w,string value){byte[] b=new byte[8];Encoding.ASCII.GetBytes(value,0,value.Length,b,0);w.Write(b);}
        static void Word(BinaryWriter w,int value){w.Write((short)value);}
        public static void Fixture(Rom rom,string path){Map m=AdvancedTests.Empty(rom,0);int texture=rom.MakeRoom(0,1024,1024).RoomTexture;AdvancedTests.Rect(m,-256,-128,0,128,texture);AdvancedTests.Rect(m,0,-128,256,128,texture);m.Walls.First(w=>m.Vertices[w.Start].X==256&&m.Vertices[w.End].X==256).Type=11;
            var lumps=new List<WadFile.Lump>();foreach(string level in new[]{"E1M1","E1M2"}){lumps.Add(new WadFile.Lump{Name=level,Data=new byte[0]});lumps.Add(new WadFile.Lump{Name="VERTEXES",Data=Data(w=>{foreach(Point p in m.Vertices){Word(w,p.X);Word(w,p.Y);}})});
                var faces=new List<Face>();var records=new List<int[]>();foreach(Wall line in m.Walls){int front=faces.Count;faces.Add(GeometryTools.Front(m,line));int back=65535;if(line.BackFace>=0){back=faces.Count;faces.Add(GeometryTools.Back(m,line));}records.Add(new[]{line.Start,line.End,back==65535?1:4,line.Type,line.Tag,front,back});}
                lumps.Add(new WadFile.Lump{Name="LINEDEFS",Data=Data(w=>{foreach(int[] r in records)foreach(int n in r)Word(w,n);})});lumps.Add(new WadFile.Lump{Name="SIDEDEFS",Data=Data(w=>{foreach(Face f in faces){Word(w,0);Word(w,0);Name(w,"STARTAN2");Name(w,"STARTAN2");Name(w,f.Solid?"STARTAN2":"-");Word(w,f.Near);}})});
                lumps.Add(new WadFile.Lump{Name="SECTORS",Data=Data(w=>{foreach(Sector s in m.Sectors){Word(w,0);Word(w,128);Name(w,"CEIL1_1");Name(w,"CEIL1_1");Word(w,192);Word(w,0);Word(w,0);}})});lumps.Add(new WadFile.Lump{Name="THINGS",Data=Data(w=>{Word(w,-128);Word(w,0);Word(w,0);Word(w,1);Word(w,7);})});}
            byte[] wad=Data(w=>{w.Write(Encoding.ASCII.GetBytes("PWAD"));w.Write(lumps.Count);w.Write(12+lumps.Sum(l=>l.Data.Length));foreach(var l in lumps)w.Write(l.Data);int offset=12;foreach(var l in lumps){w.Write(offset);w.Write(l.Data.Length);Name(w,l.Name);offset+=l.Data.Length;}});Bin.Atomic(path,wad);
        }
        public static void Run(string romPath,string output){string resources=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"editor-data");var rom=new Rom(romPath,resources);Context.Rom=rom;
            Check(rom.FlatTextures.SequenceEqual(Enumerable.Range(1,255)),"all requested palette IDs available");
            int id=rom.WallTextures.First(i=>i>=4);int header=0x1b007e+Bin.U16(rom.Bytes,0x1b0000+id),height=rom.Bytes[header]&254;if(height==0)height=256;int table=header+2,bank=rom.Bytes[table+2],address=Bin.U16(rom.Bytes,table),ptr=bank<0x40?(bank&63)*0x8000+(address&32767):(bank&31)*65536+address;ptr++;Color rawFirst=AssetPreview.Palette(rom,rom.Bytes[ptr]);using(var preview=new AssetPreview()){preview.ShowWall(rom,id);using(var decoded=preview.CopyImage())Check(decoded.GetPixel(0,height-1).ToArgb()==rawFirst.ToArgb(),"bottom-up ROM columns are displayed top-down");}
            using(var form=new EditorForm(null)){Call(form,"LoadRom",romPath);Rom model=(Rom)Field(form,"rom");Map m=MapTemplates.Starter(model,0);model.Project.Maps[0]=m;Call(form,"RefreshMaps",0,"");var canvas=(MapCanvas)Field(form,"canvas");float before=(float)Field(canvas,"cx");Call(canvas,"OnKeyDown",new KeyEventArgs(Keys.Right));Check((float)Field(canvas,"cx")>before,"arrow pans 2D viewport");
                Call(form,"SelectMode","Walls");canvas.Selection.Clear();canvas.Selection.Add(0);canvas.Selection.Add(1);canvas.OnSelect(1);var grid=(PropertyGrid)Field(form,"properties");Check(grid.SelectedObjects.Length==2,"Ctrl-style canvas selection binds both property objects");foreach(object value in grid.SelectedObjects)TypeDescriptor.GetProperties(value)["Impassable"].SetValue(value,true);Call(form,"Commit");Check((m.Walls[0].Flags&8)!=0&&(m.Walls[1].Flags&8)!=0,"bulk collision edit reaches both linedefs");
                int old=m.Things[0].X;m.Things[0].X=old+16;Call(form,"Commit");m.Things[0].X=old+32;Call(form,"Commit");Call(form,"History",false);Map current=(Map)Field(form,"map");Check(current.Things[0].X==old+16,"one undo restores exactly one edit");Call(form,"History",true);current=(Map)Field(form,"map");Check(current.Things[0].X==old+32,"redo restores one edit");string snapshot=(string)Call(form,"Snapshot");Check(snapshot.Length<10000,"undo serializes one small map instead of 22 maps");
                Message repeated=Message.Create(IntPtr.Zero,0x100,new IntPtr((int)Keys.Z),new IntPtr(0x40000000));var method=typeof(EditorForm).GetMethod("ProcessCmdKey",BindingFlags.Instance|BindingFlags.NonPublic);method.Invoke(form,new object[]{repeated,Keys.Control|Keys.Z});Check(((Map)Field(form,"map")).Things[0].X==old+32,"held undo key repeat is ignored");
            }
            Context.Rom=rom;string wadPath=Path.Combine(output,"converter-fixture.wad");Fixture(rom,wadPath);var wad=new WadFile(wadPath);Check(wad.Levels.Count==2,"multiple WAD maps detected");var converter=new WadConverter(rom,resources);Map merged=converter.Import(wad,"E1M1",0,true);Check(merged.Sectors.Count==2,"sector with exit action protected from merge");Map mergeMap=converter.Import(wad,"E1M1",0,false);foreach(Wall line in mergeMap.Walls)line.Type=0;converter.Merge(mergeMap);Check(mergeMap.Sectors.Count==1&&mergeMap.Walls.Count==6,"identical static sectors merge and shared wall is removed");
            var multiRom=new Rom(romPath,resources);var multi=new WadConverter(multiRom,resources);multi.Options.BestFit=false;byte[] image=multi.Convert(wad,wad.Levels.ToArray(),true);byte[] source=(byte[])multiRom.Bytes.Clone();Buffer.BlockCopy(image,0,multiRom.Bytes,0,image.Length);Check(multiRom.Read(0).Things.Single(t=>t.Type==0).X==-128,"converted first level reimports as native map");Check(multiRom.Read(1).Sectors.Count==2,"second converted map reimports");Buffer.BlockCopy(source,0,multiRom.Bytes,0,source.Length);Check(image[0x1ffb4e]==255&&image[0x1ffb55]==255,"custom campaign bypasses original early difficulty endings");Check(Bin.U16(image,0x7fdc)==(Bin.U16(image,0x7fde)^65535),"ROM checksum pair valid");int checksum=image.Sum(b=>(int)b)&65535;Check(checksum==Bin.U16(image,0x7fde),"ROM checksum matches exported bytes");Bin.Atomic(Path.Combine(output,"converter-two-level.sfc"),image);multiRom.SaveProject(Path.Combine(output,"converter-two-level.sned"));
            var singleRom=new Rom(romPath,resources);byte[] single=new WadConverter(singleRom,resources).Convert(wad,new[]{"E1M2"},true);Check(!single.SequenceEqual(image),"level filtering changes campaign output");Bin.Atomic(Path.Combine(output,"converter-single.sfc"),single);
            int differences=0;for(int i=0;i<image.Length;i++)if(single[i]!=image[i])differences++;Check(differences>0,"single-level export distinct");bool refused=false;try{ConverterProgram.Convert(romPath,wad,romPath,new[]{"E1M1"},true,false,resources);}catch(InvalidDataException){refused=true;}Check(refused,"base ROM overwrite rejected");
            File.WriteAllText(Path.Combine(output,"interaction-converter-results.txt"),"PASS: arrow panning; bulk property binding; one-step undo/redo and repeat suppression; per-map snapshots; palette range; texture orientation; multi-level WAD import; conservative sector merge; native ROM reimport; checksum; level filtering; base ROM protection.\r\n");
        }
    }
}
